package jetbrains.mps.lang.core.intentions;

/*Generated by MPS */


public final class SuppressionUtil {
  private static final int MAX_LENGTH = 80;
  private static final String ELLIPSIS = "...";

  public static String ensureNotTooLong(String message) {
    if (message == null) {
      return null;
    }
    String normalized = message.replaceAll("[\\r\\n]+", " ");
    if (normalized.length() <= MAX_LENGTH) {
      return normalized;
    }
    int limit = MAX_LENGTH - ELLIPSIS.length();
    String prefix = normalized.substring(0, limit);
    if (!(Character.isWhitespace(normalized.charAt(limit)))) {
      int lastSpace = prefix.lastIndexOf(' ');
      if (lastSpace > limit / 2) {
        prefix = prefix.substring(0, lastSpace);
      }
    }
    return prefix.stripTrailing() + ELLIPSIS;
  }
}
